cd /Users/myankelev/Code/random/cipher-box
_GSD_SHIM_NAME="gsd-tools.cjs"
GSD_TOOLS="$(git rev-parse --show-toplevel)/.claude/gsd-core/bin/${_GSD_SHIM_NAME}"
gsd_run() { node "$GSD_TOOLS" "$@"; }
echo "===PLAN:PRE HOOKS==="
gsd_run loop render-hooks plan:pre --raw 2>/dev/null | node -e "
const o=JSON.parse(require('fs').readFileSync(0,'utf8'));
const hooks=o.activeHooks||o.hooks||[];
console.log('activeHooks count:', hooks.length);
for (const h of hooks) {
  console.log('---');
  console.log('kind:', h.kind, '| capId:', h.capId, '| into:', h.into||'', '| blocking:', h.blocking);
  if (h.ref) console.log('ref:', JSON.stringify(h.ref));
  if (h.check) console.log('check:', JSON.stringify(h.check));
  if (h.configValues) console.log('configValues:', JSON.stringify(h.configValues));
}
" 2>&1 | head -60
echo ""
echo "===UI PLAN GATE==="
gsd_run check ui-plan-gate "68.2" --raw 2>/dev/null || echo "gate check failed"

cd /Users/myankelev/Code/random/cipher-box
_GSD_SHIM_NAME="gsd-tools.cjs"
GSD_TOOLS="$(git rev-parse --show-toplevel)/.claude/gsd-core/bin/${_GSD_SHIM_NAME}"
gsd_run() { node "$GSD_TOOLS" "$@"; }
echo "===FULL RAW plan:pre JSON (top-level keys + any ui capId)==="
gsd_run loop render-hooks plan:pre --raw 2>/dev/null | node -e "
const o=JSON.parse(require('fs').readFileSync(0,'utf8'));
console.log('top-level keys:', Object.keys(o).join(', '));
const hooks=o.activeHooks||o.hooks||[];
// Show every hook fully
const uiHooks = hooks.filter(h => (h.capId||'').includes('ui') || JSON.stringify(h).includes('ui.plan-gate') || JSON.stringify(h).includes('ui-plan-gate'));
console.log('UI-related hooks in activeHooks:', uiHooks.length);
console.log(JSON.stringify(uiHooks, null, 2));
// Also check if there is an inactiveHooks or allHooks
if (o.inactiveHooks) console.log('inactiveHooks capIds:', o.inactiveHooks.map(h=>h.capId).join(', '));
"
